import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import {
  AlertCircle, ArrowUpRight, BriefcaseBusiness, CalendarDays, Check, ChevronDown, CircleDollarSign,
  Clock3, FileCheck2, FileText, Filter, Headphones, Laptop, LifeBuoy, Mail, MapPin, MoreHorizontal,
  Package, Plus, Search, ShieldCheck, TicketCheck, UserRound, Users, WalletCards, Wrench, X,
} from "lucide-react";
import type { ApprovalRequest, Asset, CalendarEvent, Customer, Employee, Expense, PageId, SupportTicket, Vendor } from "./types";

type OpsProps = { page: PageId; role: string; onToast: (message: string) => void };
type OpsModal = "expense" | "request" | "asset" | "vendor" | "ticket" | "customer" | null;

async function opsApi<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, { credentials: "include", ...init });
  if (!response.ok) throw new Error((await response.json().catch(() => null))?.error || "Request failed");
  return response.json() as Promise<T>;
}

const naira = (value: number) => `₦${new Intl.NumberFormat("en-NG", { maximumFractionDigits: 0 }).format(value)}`;
const compactNaira = (value: number) => `₦${new Intl.NumberFormat("en-NG", { notation: "compact", maximumFractionDigits: 1 }).format(value)}`;
const titleCase = (value: string) => value.replace(/_/g, " ").replace(/\b\w/g, (match) => match.toUpperCase());
const isFinancialRequest = (request: ApprovalRequest) => (typeof request.amount === "number" && Number.isFinite(request.amount)) || ["expense", "purchase", "budget", "payroll", "reimbursement", "payment", "financial", "asset purchase"].includes(request.requestType.trim().toLowerCase());

function OpsHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action && <div className="page-header-action">{action}</div>}</div>;
}

function OpsCardHeading({ title, subtitle, action }: { title: string; subtitle?: string; action?: ReactNode }) {
  return <div className="card-heading"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div>;
}

function OpsStat({ icon: Icon, tone, label, value, detail }: { icon: typeof WalletCards; tone: string; label: string; value: string; detail: string }) {
  return <div className="card ops-stat"><span className={`ops-stat-icon ${tone}`}><Icon size={17} /></span><span className="ops-stat-label">{label}</span><strong>{value}</strong><small>{detail}</small></div>;
}

function Status({ value }: { value: string }) {
  return <span className={`status-badge ${value.toLowerCase().replace(/ /g, "_")}`}>{titleCase(value)}</span>;
}

function OpsTableToolbar({ placeholder, onSearch, action }: { placeholder: string; onSearch?: (value: string) => void; action?: ReactNode }) {
  return <div className="table-toolbar"><div className="table-search"><Search size={16} /><input placeholder={placeholder} onChange={(event) => onSearch?.(event.target.value)} /></div><div className="toolbar-actions">{action || <button className="filter-button"><Filter size={14} /> Filters <ChevronDown size={14} /></button>}</div></div>;
}

export function OperationalWorkspace({ page, role, onToast }: OpsProps) {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [requests, setRequests] = useState<ApprovalRequest[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [tickets, setTickets] = useState<SupportTicket[]>([]);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loadError, setLoadError] = useState("");
  const [modal, setModal] = useState<OpsModal>(null);

  const loadData = async () => {
      try {
        const [expenseData, requestData, assetData, vendorData, ticketData, eventData, customerData] = await Promise.all([
          opsApi<{ data: Expense[] }>("/api/expenses"), opsApi<{ data: ApprovalRequest[] }>("/api/requests"), opsApi<{ data: Asset[] }>("/api/assets"), opsApi<{ data: Vendor[] }>("/api/vendors"), opsApi<{ data: SupportTicket[] }>("/api/tickets"), opsApi<{ data: CalendarEvent[] }>("/api/calendar"), opsApi<{ data: Customer[] }>("/api/customers"),
        ]);
        setExpenses(expenseData.data); setRequests(requestData.data); setAssets(assetData.data); setVendors(vendorData.data); setTickets(ticketData.data); setEvents(eventData.data); setCustomers(customerData.data); setLoadError("");
      } catch (cause) {
        setLoadError(cause instanceof Error ? cause.message : "Could not load workspace records. Refresh and try again.");
      }
    };
  useEffect(() => { void loadData(); }, []);

  const createExpense = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries());
    const amount = Number(values.amount);
    const local: Expense = { id: `local-${Date.now()}`, employee: "Amaka Okafor", category: String(values.category), amount, currency: "NGN", expenseDate: new Date(String(values.expenseDate)).toLocaleDateString("en-NG", { day: "2-digit", month: "short", year: "numeric" }), description: String(values.description), status: "submitted" };
    let savedRequestId = "";
    try { const saved = await opsApi<{ id: string; requestId: string; employee: string }>("/api/expenses", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(values) }); local.id = saved.id; local.employee = saved.employee; savedRequestId = saved.requestId; }
    catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not submit expense"); return; }
    setExpenses((current) => [local, ...current]); setRequests((current) => [{ id: savedRequestId, requestType: "Expense", title: local.description, requester: local.employee, amount, status: "pending", requiredRole: "CEO", createdAt: new Date().toISOString() }, ...current]); setModal(null); onToast("Expense submitted for CEO approval");
  };

  const createRequest = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries());
    try {
      const saved = await opsApi<{ id: string; requiredRole: string; status: "pending" }>("/api/requests", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(values) });
      const amount = values.amount ? Number(values.amount) : undefined;
      setRequests((current) => [{ id: saved.id, requestType: String(values.requestType), title: String(values.title), requester: "You", amount, status: saved.status, requiredRole: saved.requiredRole, createdAt: "Just now" }, ...current]);
      setModal(null); onToast(`Request submitted. ${saved.requiredRole} has been notified by email and in-app.`);
    } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not submit request"); }
  };

  const reviewRequest = async (item: ApprovalRequest, status: "approved" | "rejected") => {
    const reason = status === "rejected" ? window.prompt("Give the requester a clear reason for rejecting this request:")?.trim() : "";
    if (status === "rejected" && !reason) { if (reason !== null) onToast("A rejection reason is required."); return; }
    try {
      const result = await opsApi<{ status: "approved" | "rejected" | "pending"; requiredRole?: string }>(`/api/requests/${item.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ status, reason }) });
      setRequests((current) => current.map((request) => request.id === item.id ? { ...request, status: result.status, requiredRole: result.requiredRole || request.requiredRole } : request));
      if (item.requestType === "Expense" && result.status !== "pending") setExpenses((current) => current.map((expense) => expense.description === item.title ? { ...expense, status: result.status as Expense["status"] } : expense));
      onToast(result.status === "pending" ? `Request sent to ${result.requiredRole || item.requiredRole} for approval.` : `Request ${status}`);
    } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not process approval"); }
  };

  const createAsset = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); const item: Asset = { id: `local-${Date.now()}`, assetTag: "AST-PENDING", name: String(values.name), category: String(values.category), serialNumber: String(values.serialNumber || "—"), status: "available", location: String(values.location || "Unassigned"), value: Number(values.value || 0) };
    try { const saved = await opsApi<{ id: string; assetTag: string }>("/api/assets", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(values) }); item.id = saved.id; item.assetTag = saved.assetTag; } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not add asset"); return; }
    setAssets((current) => [item, ...current]); setModal(null); onToast("Asset added to the register");
  };

  const createVendor = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); const item: Vendor = { id: `local-${Date.now()}`, name: String(values.name), category: String(values.category), contactName: String(values.contactName), email: String(values.email), status: "review", contractEnd: String(values.contractEnd || "Not set"), spend: 0 };
    try { const saved = await opsApi<{ id: string }>("/api/vendors", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(values) }); item.id = saved.id; } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not add vendor"); return; }
    setVendors((current) => [item, ...current]); setModal(null); onToast("Vendor added for review");
  };

  const createTicket = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); const item: SupportTicket = { id: `local-${Date.now()}`, ticketNumber: "ZD-PENDING", subject: String(values.subject), category: String(values.category), priority: String(values.priority) as SupportTicket["priority"], status: "open", requester: "Amaka Okafor", createdAt: "Just now" };
    try { const saved = await opsApi<{ id: string; ticketNumber: string }>("/api/tickets", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(values) }); item.id = saved.id; item.ticketNumber = saved.ticketNumber; } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not create ticket"); return; }
    setTickets((current) => [item, ...current]); setModal(null); onToast("Support ticket created");
  };

  const createCustomer = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); const item: Customer = { id: `local-${Date.now()}`, name: String(values.name), company: String(values.company), email: String(values.email), stage: String(values.stage) as Customer["stage"], value: Number(values.value || 0), owner: "Amaka Okafor", lastActivity: "Just now" };
    try { const saved = await opsApi<{ id: string }>("/api/customers", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(values) }); item.id = saved.id; } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not add customer"); return; }
    setCustomers((current) => [item, ...current]); setModal(null); onToast("Customer added to the pipeline");
  };

  const shared = { expenses, requests, assets, vendors, tickets, events, customers, role, onToast, openModal: setModal, reviewRequest, refreshData: loadData };
  return <>{loadError && <div className="work-error" role="alert">Live operational data could not be loaded: {loadError}</div>}{page === "expenses" && <ExpensesPage {...shared} />}{page === "requests" && <RequestsPage {...shared} />}{page === "assets" && <AssetsPage {...shared} />}{page === "vendors" && <VendorsPage {...shared} />}{page === "helpdesk" && <HelpdeskPage {...shared} />}{page === "calendar" && <CalendarPage {...shared} />}{page === "customers" && <CustomersPage {...shared} />}{page === "budgets" && <BudgetsPage onToast={onToast} />}
    {modal === "expense" && <OpsModal title="Submit expense" onClose={() => setModal(null)}><form className="modal-form" onSubmit={createExpense}><div className="form-grid"><label>Category<select name="category" defaultValue="Software"><option>Software</option><option>Travel</option><option>Operations</option><option>Client entertainment</option><option>Learning</option></select></label><label>Amount (NGN)<input name="amount" type="number" min="1" required placeholder="150000" /></label></div><label>Expense date<input name="expenseDate" type="date" required defaultValue="2026-09-28" /></label><label>Description<textarea name="description" required placeholder="What was this expense for?" /></label><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setModal(null)}>Cancel</button><button className="button primary"><WalletCards size={16} /> Submit claim</button></div></form></OpsModal>}
    {modal === "request" && <OpsModal title="New operational request" onClose={() => setModal(null)}><form className="modal-form" onSubmit={createRequest}><label>Request type<select name="requestType" defaultValue="Operational"><option>Operational</option><option>Access</option><option>HR</option><option>Leave</option><option>Purchase</option><option>Budget</option><option>Other</option></select></label><label>Request title<input name="title" required maxLength={120} placeholder="What do you need approved?" /></label><label>Details<textarea name="details" required maxLength={2000} placeholder="Add the context the approver needs." /></label><label>Amount (NGN) <small>Optional; any financial amount routes to the CEO</small><input name="amount" type="number" min="0.01" step="0.01" placeholder="Leave blank if not financial" /></label><div className="security-note"><ShieldCheck size={17} /><div><strong>Approver is set by organization workflow</strong><span>Finance requests always require CEO approval.</span></div></div><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setModal(null)}>Cancel</button><button className="button primary"><FileCheck2 size={16} /> Submit for approval</button></div></form></OpsModal>}
    {modal === "asset" && <OpsModal title="Add asset" onClose={() => setModal(null)}><form className="modal-form" onSubmit={createAsset}><div className="form-grid"><label>Asset name<input name="name" required placeholder="MacBook Pro" /></label><label>Category<select name="category" defaultValue="Laptop"><option>Laptop</option><option>Mobile</option><option>Equipment</option><option>Vehicle</option><option>Software license</option></select></label></div><div className="form-grid"><label>Serial number<input name="serialNumber" placeholder="Serial / licence ID" /></label><label>Value (NGN)<input name="value" type="number" min="0" placeholder="500000" /></label></div><label>Location<input name="location" placeholder="Lagos office" /></label><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setModal(null)}>Cancel</button><button className="button primary"><Package size={16} /> Add asset</button></div></form></OpsModal>}
    {modal === "vendor" && <OpsModal title="Add vendor" onClose={() => setModal(null)}><form className="modal-form" onSubmit={createVendor}><div className="form-grid"><label>Company name<input name="name" required placeholder="Vendor company" /></label><label>Category<select name="category" defaultValue="Technology"><option>Technology</option><option>Facilities</option><option>Professional services</option><option>Logistics</option></select></label></div><div className="form-grid"><label>Contact name<input name="contactName" placeholder="Contact person" /></label><label>Email<input name="email" type="email" placeholder="vendor@example.com" /></label></div><label>Contract end<input name="contractEnd" type="date" /></label><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setModal(null)}>Cancel</button><button className="button primary"><BriefcaseBusiness size={16} /> Add vendor</button></div></form></OpsModal>}
    {modal === "ticket" && <OpsModal title="Create support ticket" onClose={() => setModal(null)}><form className="modal-form" onSubmit={createTicket}><label>Subject<input name="subject" required placeholder="What do you need help with?" /></label><div className="form-grid"><label>Category<select name="category" defaultValue="IT"><option>IT</option><option>HR</option><option>Finance</option><option>Facilities</option><option>Other</option></select></label><label>Priority<select name="priority" defaultValue="medium"><option>low</option><option>medium</option><option>high</option><option>urgent</option></select></label></div><label>Description<textarea name="description" placeholder="Add useful context for the support team" /></label><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setModal(null)}>Cancel</button><button className="button primary"><LifeBuoy size={16} /> Create ticket</button></div></form></OpsModal>}
    {modal === "customer" && <OpsModal title="Add customer" onClose={() => setModal(null)}><form className="modal-form" onSubmit={createCustomer}><div className="form-grid"><label>Contact name<input name="name" required placeholder="Customer contact" /></label><label>Company<input name="company" placeholder="Company name" /></label></div><div className="form-grid"><label>Email<input name="email" type="email" required placeholder="customer@example.com" /></label><label>Deal value (NGN)<input name="value" type="number" min="0" placeholder="1000000" /></label></div><label>Pipeline stage<select name="stage" defaultValue="lead"><option value="lead">Lead</option><option value="qualified">Qualified</option><option value="proposal">Proposal</option><option value="negotiation">Negotiation</option></select></label><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setModal(null)}>Cancel</button><button className="button primary"><Users size={16} /> Add customer</button></div></form></OpsModal>}
  </>;
}

type SharedProps = { expenses: Expense[]; requests: ApprovalRequest[]; assets: Asset[]; vendors: Vendor[]; tickets: SupportTicket[]; events: CalendarEvent[]; customers: Customer[]; role: string; onToast: (message: string) => void; openModal: (modal: Exclude<OpsModal, null>) => void; reviewRequest: (request: ApprovalRequest, status: "approved" | "rejected") => void; refreshData: () => Promise<void> };

function ExpensesPage({ expenses, onToast, openModal }: SharedProps) {
  const [query, setQuery] = useState(""); const filtered = useMemo(() => expenses.filter((item) => `${item.employee} ${item.category} ${item.description}`.toLowerCase().includes(query.toLowerCase())), [expenses, query]); const total = expenses.reduce((sum, item) => sum + item.amount, 0); const pending = expenses.filter((item) => item.status === "submitted").reduce((sum, item) => sum + item.amount, 0); const approved = expenses.filter((item) => item.status === "approved" || item.status === "paid").length;
  return <><OpsHeader eyebrow="FINANCE / EXPENSES" title="Expenses" description="Submit, review and pay expenses with a clear approval trail." action={<button className="button primary" onClick={() => openModal("expense")}><Plus size={16} /> Submit expense</button>} /><div className="ops-stat-grid"><OpsStat icon={CircleDollarSign} tone="blue" label="Total recorded" value={compactNaira(total)} detail="Visible expense records" /><OpsStat icon={Clock3} tone="orange" label="Awaiting approval" value={compactNaira(pending)} detail="Submitted claims" /><OpsStat icon={Check} tone="green" label="Approved claims" value={String(approved)} detail="Visible records" /><OpsStat icon={ShieldCheck} tone="violet" label="Policy compliance" value="Not configured" detail="Set spend rules to measure" /></div><section className="card table-card"><div className="ops-table-heading"><div><OpsCardHeading title="Expense register" subtitle="Every claim is linked to a request and audit history." /></div><div className="expense-policy"><ShieldCheck size={14} /> CEO approval enforced for financial requests</div></div><OpsTableToolbar placeholder="Search employee, category or description" onSearch={setQuery} action={<><span className="filter-button">All statuses</span><button className="filter-button" onClick={() => onToast("CSV export is not yet available. You can review the filtered register here.")}><FileText size={14} /> Export</button></>} /><div className="table-scroll"><table><thead><tr><th>Claim</th><th>Category</th><th>Date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>{filtered.map((item) => <tr key={item.id}><td><div className="employee-cell"><div className="avatar avatar-small">{item.employee.split(" ").map((word) => word[0]).join("")}</div><div><strong>{item.description}</strong><span>{item.employee}{item.project ? ` · ${item.project}` : ""}</span></div></div></td><td>{item.category}</td><td>{item.expenseDate}</td><td><strong>{naira(item.amount)}</strong></td><td><Status value={item.status} /></td><td><button className="text-button" onClick={() => onToast(`Expense ${item.id} · ${item.description} · ${naira(item.amount)} · ${item.status}`)}>Details</button></td></tr>)}</tbody></table></div></section></>;
}

function RequestsPage({ requests, role, onToast, openModal, reviewRequest }: SharedProps) {
  const pending = requests.filter((item) => item.status === "pending");
  const [showWorkflows, setShowWorkflows] = useState(false);
  const [workflows, setWorkflows] = useState<Record<string, string>>({ Operational: "Manager", Access: "Manager", HR: "HR Admin", Leave: "HR Admin", Other: "Manager" });
  const [workflowError, setWorkflowError] = useState(""); const [savingWorkflow, setSavingWorkflow] = useState(false);
  const openWorkflows = async () => { setWorkflowError(""); try { const result = await opsApi<{ workflows: Record<string, string> }>("/api/approval-workflows"); setWorkflows(result.workflows); setShowWorkflows(true); } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not load approval workflows"); } };
  const saveWorkflows = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setSavingWorkflow(true); setWorkflowError(""); try { const result = await opsApi<{ workflows: Record<string, string> }>("/api/approval-workflows", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ workflows }) }); setWorkflows(result.workflows); setShowWorkflows(false); onToast("Approval routing saved. Financial requests will always go to the CEO."); } catch (cause) { setWorkflowError(cause instanceof Error ? cause.message : "Could not save approval workflows"); } finally { setSavingWorkflow(false); } };
  return <>
    <OpsHeader eyebrow="FINANCE / WORKFLOW" title="Requests & approvals" description="Financial requests always route to the CEO; configure routing for other request types." action={<><button className="button secondary" onClick={() => void openWorkflows()}><Wrench size={16} /> Configure workflows</button><button className="button primary" onClick={() => openModal("request")}><Plus size={16} /> New request</button></>} />
    <div className="request-layout">
      <section className="card request-inbox">
        <div className="request-summary"><div><span>Open approval queue</span><strong>{pending.length}</strong><small>Requests waiting on your role</small></div><div className="request-ring"><span>{requests.length ? Math.round(requests.filter((item) => item.status === "approved" || item.status === "paid").length / requests.length * 100) : 0}%</span><small>approved</small></div></div>
        <div className="request-filters"><button className="active">All <b>{requests.length}</b></button><button>Expenses <b>{requests.filter((item) => item.requestType === "Expense").length}</b></button><button>Leave <b>{requests.filter((item) => item.requestType === "Leave").length}</b></button><button>Other <b>{requests.filter((item) => !["Expense", "Leave"].includes(item.requestType)).length}</b></button></div>
        {requests.map((item) => {
          const financial = isFinancialRequest(item);
          const requiredRole = financial ? "CEO" : item.requiredRole;
          const canDecide = role === requiredRole || (!financial && role === "Organization Admin");
          return <div className="request-row" key={item.id}>
            <span className={`request-type ${item.requestType.toLowerCase()}`}><FileCheck2 size={16} /></span>
            <div className="request-copy"><div><strong>{item.title}</strong><Status value={item.status} /></div><span>{item.requestType} · {item.requester} · {item.createdAt}{item.details ? ` · ${item.details}` : ""}</span></div>
            {typeof item.amount === "number" && <strong className="request-amount">{naira(item.amount)}</strong>}
            {item.status === "pending" ? canDecide ? <div className="request-actions"><button className="approve-button" aria-label={`Approve ${item.title}`} onClick={() => reviewRequest(item, "approved")}><Check size={14} /></button><button className="reject-button" aria-label={`Reject ${item.title}`} onClick={() => reviewRequest(item, "rejected")}><X size={14} /></button></div> : <span className="request-amount">Awaiting {requiredRole}</span> : <button className="icon-button" onClick={() => onToast("Request history opened")}><MoreHorizontal size={17} /></button>}
          </div>;
        })}
      </section>
      <aside className="card workflow-card"><OpsCardHeading title="Approval policy" subtitle="Financial requests of every value" /><div className="workflow-steps"><div><span>1</span><div><strong>Requester</strong><small>Submit supporting details</small></div></div><i></i><div><span>2</span><div><strong>CEO</strong><small>Final approval required</small></div></div><i></i><div><span>3</span><div><strong>Audit trail</strong><small>Record the decision</small></div></div></div><div className="workflow-note"><ShieldCheck size={15} /><span>Non-financial defaults: {Object.entries(workflows).map(([category, approver]) => `${category} → ${approver}`).join(" · ")}. Financial routing is fixed to the CEO.</span></div></aside>
    </div>
    {showWorkflows && <OpsModal title="Approval routing" onClose={() => setShowWorkflows(false)}><form className="modal-form" onSubmit={(event) => void saveWorkflows(event)}>{workflowError && <div className="work-error">{workflowError}</div>}{Object.keys(workflows).map((category) => <label key={category}>{category} requests<select value={workflows[category]} onChange={(event) => setWorkflows((current) => ({ ...current, [category]: event.target.value }))}><option>Manager</option><option>HR Admin</option><option>CEO</option></select></label>)}<div className="security-note"><ShieldCheck size={17} /><div><strong>Financial approvals cannot be rerouted</strong><span>Expenses, purchases and requests with a monetary amount always require CEO approval.</span></div></div><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setShowWorkflows(false)}>Cancel</button><button className="button primary" disabled={savingWorkflow}>{savingWorkflow ? "Saving…" : "Save routing"}</button></div></form></OpsModal>}
  </>;
}

function AssetsPage({ assets, onToast, openModal, refreshData }: SharedProps) {
  const [selected, setSelected] = useState<Asset | null>(null); const [history, setHistory] = useState<{ id: string; action: string; notes: string | null; createdAt: string; employee: string | null }[]>([]); const [people, setPeople] = useState<Employee[]>([]); const [busy, setBusy] = useState(false);
  useEffect(() => { if (!selected) return; void Promise.all([opsApi<{ data: typeof history }>(`/api/assets/${selected.id}/history`), opsApi<{ data: Employee[] }>("/api/employees")]).then(([records, employees]) => { setHistory(records.data); setPeople(employees.data); }).catch((cause) => onToast(cause instanceof Error ? cause.message : "Could not load asset history")); }, [selected?.id]);
  const saveAsset = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selected) return; setBusy(true); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); try { await opsApi(`/api/assets/${selected.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ status: values.status, assignedEmployeeId: values.assignedEmployeeId || null, notes: values.notes }) }); await refreshData(); const result = await opsApi<{ data: typeof history }>(`/api/assets/${selected.id}/history`); setHistory(result.data); onToast("Asset assignment and history updated."); } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not update asset"); } finally { setBusy(false); } };
  const counts = { all: assets.length, assigned: assets.filter((item) => item.status === "assigned").length, available: assets.filter((item) => item.status === "available").length, maintenance: assets.filter((item) => item.status === "maintenance").length }; const bookValue = assets.reduce((sum, item) => sum + Number(item.value || 0), 0);
  return <><OpsHeader eyebrow="OPERATIONS / ASSETS" title="Asset register" description="Know what the business owns, where it is and who is accountable." action={<button className="button primary" onClick={() => openModal("asset")}><Plus size={16} /> Add asset</button>} /><div className="asset-summary"><div className="asset-value"><span>Total book value</span><strong>{compactNaira(bookValue)}</strong><small>{counts.all} tracked assets</small></div><div className="asset-counts">{[["All assets", counts.all], ["Assigned", counts.assigned], ["Available", counts.available], ["Maintenance", counts.maintenance]].map(([label, count]) => <div key={String(label)}><strong>{count}</strong><span>{label}</span></div>)}</div></div><section className="card table-card"><OpsTableToolbar placeholder="Search by asset, tag or serial number" action={<span className="filter-button">All categories</span>} /><div className="table-scroll"><table><thead><tr><th>Asset</th><th>Category</th><th>Assigned to</th><th>Location</th><th>Value</th><th>Status</th><th></th></tr></thead><tbody>{assets.map((item) => <tr key={item.id}><td><div className="employee-cell"><span className="asset-mini-icon"><Laptop size={16} /></span><div><strong>{item.name}</strong><span>{item.assetTag} · {item.serialNumber}</span></div></div></td><td>{item.category}</td><td>{item.assignee || "Unassigned"}</td><td><span className="location-pill"><MapPin size={12} />{item.location}</span></td><td>{naira(item.value)}</td><td><Status value={item.status} /></td><td><button className="text-button" onClick={() => setSelected(item)}>History / edit</button></td></tr>)}</tbody></table></div></section>{selected && <OpsModal title={`${selected.name} · ${selected.assetTag}`} onClose={() => setSelected(null)}><div className="asset-history-list">{history.map((record) => <div key={record.id}><strong>{titleCase(record.action.replace("status_", ""))}</strong><span>{record.notes || (record.employee ? `Assigned to ${record.employee}` : "Asset record updated")}</span><small>{new Date(record.createdAt).toLocaleString()}</small></div>)}</div><form className="modal-form" onSubmit={(event) => void saveAsset(event)}><label>Assigned employee<select name="assignedEmployeeId" defaultValue={selected.assignedEmployeeId || ""}><option value="">Unassigned</option>{people.filter((person) => person.status === "active").map((person) => <option key={person.id} value={person.id}>{person.firstName} {person.lastName}</option>)}</select></label><label>Asset status<select name="status" defaultValue={selected.status}><option value="available">Available</option><option value="assigned">Assigned</option><option value="maintenance">Maintenance</option><option value="retired">Retired</option></select></label><label>History note<input name="notes" maxLength={500} placeholder="Optional assignment or condition note" /></label><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setSelected(null)}>Close</button><button className="button primary" disabled={busy}>{busy ? "Saving…" : "Save asset"}</button></div></form></OpsModal>}</>;
}

function VendorsPage({ vendors, onToast, openModal, refreshData }: SharedProps) {
  const [selected, setSelected] = useState<Vendor | null>(null); const [saving, setSaving] = useState(false);
  const update = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selected) return; setSaving(true); const form = new FormData(event.currentTarget); const body = Object.fromEntries(form.entries()); try { await opsApi(`/api/vendors/${selected.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...body, contractEnd: body.contractEnd || null, spend: Number(body.spend || 0) }) }); await refreshData(); setSelected(null); onToast("Vendor profile saved."); } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not update vendor."); } finally { setSaving(false); } };
  const renewing = vendors.filter((vendor) => { const date = Date.parse(vendor.contractEnd || ""); return Number.isFinite(date) && date >= Date.now() && date <= Date.now() + 30 * 86400000; });
  return <><OpsHeader eyebrow="OPERATIONS / VENDORS" title="Vendors" description="Manage vendor relationships, contracts and renewal risk in one place." action={<button className="button primary" onClick={() => openModal("vendor")}><Plus size={16} /> Add vendor</button>} />{renewing.length > 0 && <div className="vendor-callout"><div className="vendor-callout-icon"><AlertCircle size={18} /></div><div><strong>{renewing.length} contract{renewing.length === 1 ? "" : "s"} due within 30 days</strong><span>{renewing.map((vendor) => vendor.name).join(", ")}</span></div><span>Review renewal dates</span></div>}<section className="card table-card"><OpsTableToolbar placeholder="Search vendors, contacts or services" action={<span className="filter-button">All statuses</span>} /><div className="table-scroll"><table><thead><tr><th>Vendor</th><th>Service</th><th>Primary contact</th><th>Contract end</th><th>Spend</th><th>Status</th><th></th></tr></thead><tbody>{vendors.map((vendor) => <tr key={vendor.id}><td><div className="vendor-cell"><span className="vendor-avatar">{vendor.name.split(" ").map((word) => word[0]).slice(0, 2).join("")}</span><div><strong>{vendor.name}</strong><span>{vendor.email}</span></div></div></td><td>{vendor.category}</td><td>{vendor.contactName}</td><td>{vendor.contractEnd || "Not set"}</td><td><strong>{compactNaira(vendor.spend)}</strong></td><td><Status value={vendor.status} /></td><td><button className="text-button" onClick={() => setSelected(vendor)}>Edit</button></td></tr>)}</tbody></table></div></section>{selected && <OpsModal title={`Edit vendor · ${selected.name}`} onClose={() => setSelected(null)}><form className="modal-form" onSubmit={(event) => void update(event)}><label>Vendor name<input name="name" required defaultValue={selected.name} /></label><div className="form-grid"><label>Service category<input name="category" required defaultValue={selected.category} /></label><label>Contact name<input name="contactName" defaultValue={selected.contactName} /></label></div><div className="form-grid"><label>Email<input name="email" type="email" defaultValue={selected.email} /></label><label>Contract end<input name="contractEnd" type="date" defaultValue={selected.contractEnd || ""} /></label></div><div className="form-grid"><label>Status<select name="status" defaultValue={selected.status}><option value="active">Active</option><option value="review">Under review</option><option value="expired">Expired</option></select></label><label>Recorded spend (NGN)<input name="spend" type="number" min="0" step="0.01" defaultValue={selected.spend} /></label></div><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setSelected(null)}>Cancel</button><button className="button primary" disabled={saving}>{saving ? "Saving…" : "Save vendor"}</button></div></form></OpsModal>}</>;
}

function HelpdeskPage({ tickets, onToast, openModal, refreshData }: SharedProps) {
  const [selected, setSelected] = useState<SupportTicket | null>(null); const [members, setMembers] = useState<{ id: string; fullName: string; email: string }[]>([]); const [saving, setSaving] = useState(false);
  useEffect(() => { if (!selected) return; void opsApi<{ data: typeof members }>("/api/operations/members").then((result) => setMembers(result.data)).catch((cause) => onToast(cause instanceof Error ? cause.message : "Could not load organization members")); }, [selected?.id]);
  const update = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selected) return; setSaving(true); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); try { await opsApi(`/api/tickets/${selected.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...values, assigneeId: values.assigneeId || null }) }); await refreshData(); setSelected(null); onToast("Ticket assignment and status updated."); } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not update ticket."); } finally { setSaving(false); } };
  const openCount = tickets.filter((ticket) => ticket.status !== "resolved" && ticket.status !== "closed").length; const resolved = tickets.filter((ticket) => ticket.status === "resolved" || ticket.status === "closed").length;
  return <><OpsHeader eyebrow="OPERATIONS / HELPDESK" title="Helpdesk" description="Record and track internal support requests." action={<button className="button primary" onClick={() => openModal("ticket")}><Plus size={16} /> New ticket</button>} /><div className="ops-stat-grid"><OpsStat icon={LifeBuoy} tone="blue" label="Open tickets" value={String(openCount)} detail="Current organization records" /><OpsStat icon={Clock3} tone="orange" label="High priority" value={String(tickets.filter((ticket) => (ticket.priority === "high" || ticket.priority === "urgent") && !["resolved", "closed"].includes(ticket.status)).length)} detail="Open high/urgent tickets" /><OpsStat icon={TicketCheck} tone="green" label="Resolved" value={String(resolved)} detail="Recorded resolved tickets" /><OpsStat icon={Users} tone="violet" label="Unassigned" value={String(tickets.filter((ticket) => !ticket.assignee).length)} detail="No assignee recorded" /></div><section className="card table-card"><OpsTableToolbar placeholder="Search ticket number or subject" action={<span className="filter-button">All categories</span>} /><div className="table-scroll"><table><thead><tr><th>Ticket</th><th>Category</th><th>Requester</th><th>Assignee</th><th>Priority</th><th>Status</th><th></th></tr></thead><tbody>{tickets.map((ticket) => <tr key={ticket.id}><td><div><strong className="table-primary">{ticket.subject}</strong><span className="table-secondary">{ticket.ticketNumber} · {ticket.createdAt}</span></div></td><td>{ticket.category}</td><td>{ticket.requester}</td><td>{ticket.assignee || "Unassigned"}</td><td><span className={`priority ${ticket.priority}`}>{ticket.priority}</span></td><td><Status value={ticket.status} /></td><td><button className="text-button" onClick={() => setSelected(ticket)}>Manage</button></td></tr>)}</tbody></table></div></section>{selected && <OpsModal title={`${selected.ticketNumber} · ${selected.subject}`} onClose={() => setSelected(null)}><form className="modal-form" onSubmit={(event) => void update(event)}><label>Assigned member<select name="assigneeId" defaultValue={selected.assigneeId || ""}><option value="">Unassigned</option>{members.map((member) => <option key={member.id} value={member.id}>{member.fullName} · {member.email}</option>)}</select></label><div className="form-grid"><label>Status<select name="status" defaultValue={selected.status}><option value="open">Open</option><option value="assigned">Assigned</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="closed">Closed</option></select></label><label>Priority<select name="priority" defaultValue={selected.priority}><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="urgent">Urgent</option></select></label></div><label>Description / resolution notes<textarea name="description" rows={4} defaultValue={selected.description || ""} /></label><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setSelected(null)}>Cancel</button><button className="button primary" disabled={saving}>{saving ? "Saving…" : "Save ticket"}</button></div></form></OpsModal>}</>;
}

function CalendarPage({ events, onToast }: SharedProps) { return <><OpsHeader eyebrow="WORK / CALENDAR" title="Business calendar" description="Bring leave, meetings, training and deadlines into a shared view." action={<button className="button primary" onClick={() => onToast("Calendar event composer opened")}><Plus size={16} /> Add event</button>} /><div className="calendar-shell"><section className="card calendar-main"><div className="calendar-top"><div><OpsCardHeading title="September 2026" subtitle="All organization events" /></div><div className="calendar-switch"><button>‹</button><button className="today">Today</button><button>›</button></div></div><div className="calendar-grid-head">{["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((day) => <span key={day}>{day}</span>)}</div><div className="calendar-grid">{Array.from({ length: 35 }, (_, index) => { const day = index - 3; const active = day > 0 && day <= 30; const event = day === 28 ? events[0] : day === 29 ? events[2] : null; return <div className={`calendar-cell ${day === 28 ? "today-cell" : ""}`} key={index}>{active && <><span className="calendar-date">{day}</span>{event && <button className={`calendar-event ${event.eventType.toLowerCase()}`} onClick={() => onToast(event.title)}>{event.title}</button>}{day === 30 && <button className="calendar-event leave" onClick={() => onToast("Leave calendar opened")}>Nneka on leave</button>}</>}</div>; })}</div></section><aside className="card upcoming-card"><OpsCardHeading title="Upcoming" subtitle="Next events across Zyntris" /><div className="upcoming-list">{events.map((event) => <button key={event.id} onClick={() => onToast(event.title)}><span className={`upcoming-date ${event.eventType.toLowerCase()}`}><strong>{event.startAt === "All day" ? "—" : event.startAt}</strong><small>{event.eventType}</small></span><span><strong>{event.title}</strong><small>{event.location || event.owner}</small></span><ArrowUpRight size={14} /></button>)}</div><div className="calendar-note"><CalendarDays size={15} /><span>Connect Google or Outlook Calendar from Administration.</span></div></aside></div></> }

function CustomersPage({ customers, onToast, openModal }: SharedProps) { const stages = ["lead", "qualified", "proposal", "negotiation", "won"]; return <><OpsHeader eyebrow="CUSTOMERS / CRM" title="Customer pipeline" description="Keep the customer story connected from first conversation to renewal." action={<button className="button primary" onClick={() => openModal("customer")}><Plus size={16} /> Add customer</button>} /><div className="crm-summary"><div><span>Pipeline value</span><strong>{compactNaira(customers.reduce((sum, item) => sum + item.value, 0))}</strong><small>Across active opportunities</small></div><div><span>Won this quarter</span><strong>₦7.6m</strong><small>1 customer closed</small></div><div><span>Open opportunities</span><strong>{customers.filter((item) => !["won", "lost"].includes(item.stage)).length}</strong><small>Need next activity</small></div></div><section className="card crm-board"><div className="kanban-header"><div><h2>Opportunity pipeline</h2><p>Drag-ready stages for a focused sales rhythm.</p></div><button className="filter-button"><Filter size={14} /> This quarter <ChevronDown size={14} /></button></div><div className="crm-columns">{stages.map((stage) => <div className="crm-column" key={stage}><div className="column-title"><span><i className={`column-dot ${stage}`}></i>{titleCase(stage)}</span><b>{customers.filter((item) => item.stage === stage).length}</b></div>{customers.filter((item) => item.stage === stage).map((customer) => <button className="crm-card" key={customer.id} onClick={() => onToast(`${customer.company || customer.name} profile opened`)}><div className="crm-avatar">{customer.name.split(" ").map((word) => word[0]).join("")}</div><strong>{customer.company || customer.name}</strong><span>{customer.name} · {compactNaira(customer.value)}</span><small>{customer.lastActivity}</small></button>)}</div>)}</div></section></> }

type BudgetRow = { id: string; name: string; category: string; period: string; allocated: number; spent: number; status: string };
function BudgetsPage({ onToast }: { onToast: (message: string) => void }) {
  const [rows, setRows] = useState<BudgetRow[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [showForm, setShowForm] = useState(false); const [busy, setBusy] = useState(false);
  const load = async () => { setLoading(true); setError(""); try { const result = await opsApi<{ data: BudgetRow[] }>("/api/budgets"); setRows(result.data); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not load budgets."); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, []);
  const save = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setBusy(true); const values = Object.fromEntries(new FormData(event.currentTarget).entries()); try { await opsApi("/api/budgets", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...values, allocated: Number(values.allocated), spent: Number(values.spent || 0) }) }); setShowForm(false); onToast("Budget created."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not create budget."); } finally { setBusy(false); } };
  const updateSpent = async (row: BudgetRow) => { const input = window.prompt(`Enter actual spend for ${row.name} (NGN):`, String(row.spent)); if (input === null) return; const spent = Number(input); try { await opsApi(`/api/budgets/${row.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ spent }) }); await load(); onToast("Budget actuals updated."); } catch (cause) { onToast(cause instanceof Error ? cause.message : "Could not update budget."); } };
  const allocated = rows.reduce((sum, row) => sum + row.allocated, 0); const spent = rows.reduce((sum, row) => sum + row.spent, 0); const watched = rows.filter((row) => row.status === "watch").length;
  return <><OpsHeader eyebrow="FINANCE / BUDGETS" title="Budgets" description="Make planned spend visible before it becomes a surprise." action={<button className="button primary" onClick={() => setShowForm(true)}><Plus size={16} /> Create budget</button>} />{error && <div className="work-error" role="alert">{error}</div>}<div className="ops-stat-grid"><OpsStat icon={WalletCards} tone="blue" label="Total allocated" value={compactNaira(allocated)} detail={`${rows.length} budgets`} /><OpsStat icon={CircleDollarSign} tone="orange" label="Actual spend" value={compactNaira(spent)} detail={`${allocated ? Math.round(spent / allocated * 100) : 0}% utilized`} /><OpsStat icon={ShieldCheck} tone="green" label="On track" value={String(rows.length - watched)} detail="Below 80% utilization" /><OpsStat icon={AlertCircle} tone="violet" label="Watch list" value={String(watched)} detail="At least 80% utilized" /></div><section className="card budget-list"><OpsCardHeading title="Budget performance" subtitle="Organization allocations and actual spend" />{loading ? <div className="work-loading">Loading budgets…</div> : rows.length ? rows.map((row) => { const utilization = Math.min(100, Math.round(row.spent / row.allocated * 100)); return <div className="budget-row" key={row.id}><div className="budget-title"><span className="budget-icon"><WalletCards size={16} /></span><div><strong>{row.name}</strong><small>{row.category} · {row.period}</small></div></div><div className="budget-progress"><div><i className={row.status === "watch" ? "watch" : ""} style={{ width: `${utilization}%` }} /></div><span>{utilization}%</span></div><div className="budget-numbers"><strong>{compactNaira(row.spent)}</strong><span>of {compactNaira(row.allocated)}</span></div><button className="text-button" onClick={() => void updateSpent(row)}>Update actuals</button></div>; }) : <div className="work-empty">No budgets yet. Create one to track planned and actual spending.</div>}</section>{showForm && <OpsModal title="Create budget" onClose={() => setShowForm(false)}><form className="modal-form" onSubmit={(event) => void save(event)}>{error && <div className="work-error" role="alert">{error}</div>}<label>Budget name<input name="name" required maxLength={120} /></label><div className="form-grid"><label>Category<input name="category" required maxLength={80} /></label><label>Period<input name="period" required placeholder="Q1 2027" /></label></div><div className="form-grid"><label>Allocated (NGN)<input name="allocated" type="number" min="1" step="0.01" required /></label><label>Actual spend (NGN)<input name="spent" type="number" min="0" step="0.01" defaultValue="0" /></label></div><div className="modal-actions"><button type="button" className="button secondary" onClick={() => setShowForm(false)}>Cancel</button><button className="button primary" disabled={busy}>{busy ? "Saving…" : "Create budget"}</button></div></form></OpsModal>}</>;
}

function OpsModal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="modal"><div className="modal-header"><div><div className="eyebrow">ZYNTRIS OPERATIONS</div><h2>{title}</h2></div><button className="icon-button" onClick={onClose}><X size={18} /></button></div>{children}</div></div>; }
